  // src/ui/ui-refresh.ts
  function createUIRefresh({
    getDocument,
    getActions,
    getPhases
  }) {
    function updateUI() {
      const document = getDocument();
      if (document.hidden) {
        return;
      }
      const {
        createOptionsModal,
        updateOptionsUI,
        updatePrestigeInTopBar,
        updateTotalDaysInTopBar
      } = getActions();
      const {
        ensureAutomationContainer,
        repairRuntimeAdapters,
        updateSoulGemRate,
        renderPreviousGameStats
      } = getPhases();
      let resetScrollPositionRequired = false;
      const currentScrollPosition = document.documentElement.scrollTop || document.body.scrollTop;
      createOptionsModal();
      updateOptionsUI();
      updatePrestigeInTopBar();
      const { scriptNode, created } = ensureAutomationContainer();
      if (created) {
        resetScrollPositionRequired = true;
      }
      if (repairRuntimeAdapters(scriptNode)) {
        resetScrollPositionRequired = true;
      }
      updateSoulGemRate();
      renderPreviousGameStats();
      if (resetScrollPositionRequired) {
        document.documentElement.scrollTop = document.body.scrollTop = currentScrollPosition;
      }
      updateTotalDaysInTopBar();
    }
    return { updateUI };
  }

