  // src/adapters/browser/war-settings.ts
  function createWarSettingsBrowserAdapter({
    getDocument,
    getJQuery,
    reader,
    intents,
    getActions
  }) {
    function renderControl2(node, control, actions) {
      if (control.kind === "header") {
        actions.addSettingsHeader1(node, control.label);
        return;
      }
      if (control.kind === "number") {
        actions.addSettingsNumber(
          node,
          control.settingName,
          control.label,
          control.hint
        );
        return;
      }
      if (control.kind === "toggle") {
        actions.addSettingsToggle(
          node,
          control.settingName,
          control.label,
          control.hint
        );
        return;
      }
      actions.addSettingsSelect(
        node,
        control.settingName,
        control.label,
        control.hint,
        control.options
      );
    }
    function buildWarSettings(parentNode, secondaryPrefix) {
      const model = reader.read();
      getActions().buildSettingsSection2(
        parentNode,
        secondaryPrefix,
        model.sectionId,
        model.sectionName,
        () => intents.handle({ type: "reset-war-settings", secondaryPrefix }),
        updateWarSettingsContent
      );
    }
    function updateWarSettingsContent(secondaryPrefix) {
      const model = reader.read();
      const document = getDocument();
      const scroll = document.documentElement.scrollTop || document.body.scrollTop;
      const node = getJQuery()(
        `#script_${secondaryPrefix}${model.sectionId}Content`
      );
      node.empty().off("*");
      const actions = getActions();
      for (const control of model.controls) renderControl2(node, control, actions);
      document.documentElement.scrollTop = document.body.scrollTop = scroll;
    }
    return Object.freeze({ buildWarSettings, updateWarSettingsContent });
  }

