  function createFleetSettingsEvolveAdapter({
    getFleetManagerOuter,
    getGalaxyRegions,
    getGame,
    getSettingsRaw
  }) {
    return Object.freeze({
      read() {
        const manager = requireRecord(
          getFleetManagerOuter(),
          "FleetManagerOuter"
        );
        const game = requireRecord(getGame(), "game");
        const config = requireRecord(
          manager["ShipConfig"],
          "FleetManagerOuter.ShipConfig"
        );
        const components = {};
        for (const [type, rawParts] of Object.entries(config)) {
          const parts = requireArray3(
            rawParts,
            `FleetManagerOuter.ShipConfig.${type}`
          );
          components[type] = Object.freeze(
            parts.map((raw, index) => {
              const id = requireString30(
                raw,
                `FleetManagerOuter.ShipConfig.${type}[${index}]`
              );
              return option(id, localize(game, `outer_shipyard_${type}_${id}`));
            })
          );
        }
        const rawOuterRegions = requireArray3(
          manager["Regions"],
          "FleetManagerOuter.Regions"
        );
        const outerRegionIds = rawOuterRegions.map(
          (raw, index) => requireString30(raw, `FleetManagerOuter.Regions[${index}]`)
        );
        const outerRegions = outerRegionIds.map((id) => ({
          id,
          label: readName(game, "space", id)
        }));
        const rawGalaxyRegions = requireArray3(
          getGalaxyRegions(),
          "galaxyRegions"
        );
        const galaxyRegions = rawGalaxyRegions.map(
          (raw, index) => requireString30(raw, `galaxyRegions[${index}]`)
        );
        const settings = requireRecord(getSettingsRaw(), "settingsRaw");
        const overrides = requireRecord(
          settings["overrides"],
          "settingsRaw.overrides"
        );
        const andromedaRegions = galaxyRegions.map((id) => ({
          id,
          label: id === "gxy_alien1" ? "Alien 1 System" : id === "gxy_alien2" ? "Alien 2 System" : readName(game, "galaxy", id),
          settingName: `fleet_pr_${id}`
        })).sort((a, b) => {
          const left = typeof settings[a.settingName] === "number" ? settings[a.settingName] : 0;
          const right = typeof settings[b.settingName] === "number" ? settings[b.settingName] : 0;
          return left - right;
        }).map((region) => ({
          ...region,
          ...overrides[region.settingName] ? { settingName: region.settingName } : {}
        }));
        return createFleetSettingsReadModel({
          outerControls,
          outerComponents: components,
          outerRegions,
          andromedaControls,
          andromedaRegions
        });
      }
    });
  }

  // src/application/prestige-settings.ts
  function createPrestigeSettingsIntentHandler({
    writer,
    reader,
    render,
    effects
  }) {
    return Object.freeze({
      handle(intent) {
        if (intent.type === "reset-prestige-settings") {
          writer.resetToDefaults();
          writer.persist();
          render(intent.secondaryPrefix);
          return;
        }
        const message = reader.getConfirmationText(intent.value);
        if (message !== "" && !effects.confirm(
          `${message} You may prestige immediately. Are you sure you want to toggle this prestige?`
        )) {
          writer.setPrestigeType("none");
        } else {
          writer.setPrestigeType(intent.value);
        }
        writer.setGoalStandard();
        writer.persist();
        render("");
      }
    });
  }

